  Arena arena,
  Iterable<String> strings,
) {
  final list = strings.toList(growable: false);
  final array = arena<Pointer<Utf8>>(list.length + 1);
  array[list.length] = nullptr;

  for (var i = 0; i < list.length; i++) {
