    if (pidResult < 0) {
      // ECHILD: VM reaped it
      final isDead = unix.kill(pid, 0) != 0;
      if (isDead) {
        return -1;
      }
    }

    if ((status & 0x7F) != 0) {
      return 128 + (status & 0x7F);
    }
    return (status & 0xFF00) >> 8;
  }

  @override
  void free() {
    _closePtm();
    if (_buffer != null && _buffer != nullptr) {
      calloc.free(_buffer!);
      _buffer = null;
    }
    if (_pPollFd != null && _pPollFd != nullptr) {
      calloc.free(_pPollFd!);
      _pPollFd = null;
    }
  }
}

