  // ever spawned, and killPid(0) on POSIX would mean "my whole process
  // group" — never signal a sentinel value.
  if (pty.pid > 0) Process.killPid(pty.pid, ProcessSignal.sigkill);
  if (await _exitWithin(pty, killBudget)) return;
